+    function hydrateSeries() {
+      const existing = new Set(series.map(x => x.d));
+      for (const line of tailPayload.split(/\n+/)) {
+        const [d, pStr] = line.trim().split(',');
+        if (!d || !pStr) continue;
+        if (existing.has(d)) continue;
+        series.push({ d, p: Number(pStr) });
+      }
+      series.sort((a,b) => a.d.localeCompare(b.d));
+    }
+
+    function mean(arr) {
+      let s = 0;
+      for (const x of arr) s += x;
+      return s / arr.length;
+    }
+
+    function stdev(arr) {
+      const m = mean(arr);
+      let ss = 0;
+      for (const x of arr) ss += (x - m) * (x - m);
+      return Math.sqrt(ss / (arr.length - 1));
+    }
+
+    function quantile(sortedArr, q) {
+      const pos = (sortedArr.length - 1) * q;
+      const base = Math.floor(pos);
+      const rest = pos - base;
+      if (sortedArr[base + 1] === undefined) return sortedArr[base];
+      return sortedArr[base] + rest * (sortedArr[base + 1] - sortedArr[base]);
+    }
+
+    function fmtMoney(x) {
+      const sign = x < 0 ? '-' : '';
+      const v = Math.abs(x);
+      return sign + '$' + v.toFixed(2);
+    }
+    function fmtPct(x) {
+      const sign = x < 0 ? '-' : '';
+      return sign + (Math.abs(x) * 100).toFixed(2) + '%';
+    }
+
+    hydrateSeries();
+
+    // Validate expected row count
+    if (series.length !== 675) {
+      console.warn('Unexpected series length:', series.length, '(expected 675)');
+    }
+
+    const labels = series.map(x => x.d);
+    const prices = series.map(x => x.p);
+
+    // 12m moving average
+    const ma12 = prices.map((_, i) => {
+      if (i < 11) return null;
+      let s = 0;
+      for (let k = i - 11; k <= i; k++) s += prices[k];
+      return s / 12;
+    });
+
+    // Decade stats
+    function decadeOf(dateStr) {
+      const y = Number(dateStr.slice(0,4));
+      return Math.floor(y / 10) * 10;
+    }
+
+    const decadeMap = new Map();
+    for (const pt of series) {
+      const dec = decadeOf(pt.d);
+      if (!decadeMap.has(dec)) decadeMap.set(dec, []);
+      decadeMap.get(dec).push(pt.p);
+    }
+    const decades = Array.from(decadeMap.keys()).sort((a,b)=>a-b);
+    const decadeRows = decades.map(dec => {
+      const arr = decadeMap.get(dec);
+      const m = mean(arr);
+      const sd = arr.length > 1 ? stdev(arr) : 0;
+      let min = Infinity, max = -Infinity;
+      for (const v of arr) { if (v < min) min = v; if (v > max) max = v; }
+      return {
+        decade: dec,
+        count: arr.length,
+        mean: m,
+        std: sd,
+        min,
+        max,
+        cv: m !== 0 ? (sd / m) : 0
+      };
+    });
