+      const momPct = momAbs / prices[i - 1];
+      momRows.push({ date: labels[i], price: prices[i], momAbs, momPct, absVal: Math.abs(momAbs) });
+    }
+    momRows.sort((a,b)=>b.absVal-a.absVal);
+    const momTop10 = momRows.slice(0, 10);
+
+    // Top YoY changes
+    const yoyRows = [];
