+      const yoyAbs = prices[i] - prices[i - 12];
+      const yoyPct = yoyAbs / prices[i - 12];
+      yoyRows.push({ date: labels[i], price: prices[i], yoyAbs, yoyPct, absVal: Math.abs(yoyAbs) });
+    }
+    yoyRows.sort((a,b)=>b.absVal-a.absVal);
+    const yoyTop10 = yoyRows.slice(0, 10);
+
+    // Descriptive stats
+    const sortedPrices = [...prices].sort((a,b)=>a-b);
+    const desc = [
+      ['Count (months)', String(prices.length)],
+      ['Mean', fmtMoney(mean(prices))],
+      ['Median', fmtMoney(quantile(sortedPrices, 0.50))],
+      ['Std Dev', fmtMoney(stdev(prices))],
+      ['Min', fmtMoney(sortedPrices[0])],
+      ['5th percentile', fmtMoney(quantile(sortedPrices, 0.05))],
+      ['25th percentile', fmtMoney(quantile(sortedPrices, 0.25))],
+      ['75th percentile', fmtMoney(quantile(sortedPrices, 0.75))],
+      ['95th percentile', fmtMoney(quantile(sortedPrices, 0.95))],
+      ['Max', fmtMoney(sortedPrices[sortedPrices.length - 1])]
+    ];
+
+    // Render tables
