+        <td class="num">${r.mean.toFixed(2)}</td>
+        <td class="num">${r.std.toFixed(2)}</td>
+        <td class="num">${r.min.toFixed(2)}</td>
+        <td class="num">${r.max.toFixed(2)}</td>
+        <td class="num">${r.cv.toFixed(3)}</td>
+      </tr>`).join('');
+
+    const momBody = document.getElementById('momTableBody');
+    momBody.innerHTML = momTop10.map(r => `
+      <tr>
+        <td class="date">${r.date}</td>
+        <td class="num">${r.price.toFixed(2)}</td>
+        <td class="num">${r.momAbs.toFixed(2)}</td>
+        <td class="num">${fmtPct(r.momPct)}</td>
+      </tr>`).join('');
+
+    const yoyBody = document.getElementById('yoyTableBody');
+    yoyBody.innerHTML = yoyTop10.map(r => `
+      <tr>
+        <td class="date">${r.date}</td>
+        <td class="num">${r.price.toFixed(2)}</td>
+        <td class="num">${r.yoyAbs.toFixed(2)}</td>
+        <td class="num">${fmtPct(r.yoyPct)}</td>
+      </tr>`).join('');
+
+    const descBody = document.getElementById('descStatsBody');
+    descBody.innerHTML = desc.map(([k,v]) => `
+      <tr>
+        <td>${k}</td>
+        <td class="num">${v.replace('$','')}</td>
+      </tr>`).join('');
+
