+    };
+
+    // Price chart with custom point labels (simple plugin)
+    const labelPlugin = {
+      id: 'labelPlugin',
+      afterDatasetsDraw(chart) {
+        const { ctx, chartArea } = chart;
+        if (!chartArea) return;
+        const pointsToLabel = [
+          { date: '2008-07-01', text: 'Peak 2008-07 ($132.83)' },
+          { date: '2008-10-01', text: 'Max MoM drop 2008-10 (-$26.96)' },
+          { date: '2020-04-01', text: '2020 trough window' }
+        ];
+        ctx.save();
+        ctx.fillStyle = annotationStyle.color;
+        ctx.font = `${annotationStyle.font.weight} ${annotationStyle.font.size}px ${annotationStyle.font.family}`;
+        ctx.textBaseline = 'middle';
+        for (const it of pointsToLabel) {
+          const idx = labels.indexOf(it.date);
