+
+    const decadeChart = new Chart(document.getElementById('decadeChart'), {
+      type: 'bar',
+      data: {
+        labels: decadeLabels,
+        datasets: [
+          {
+            label: 'Mean price',
+            data: decadeMeans,
+            backgroundColor: 'rgba(125,211,252,0.22)',
